public void process(GUPDiscountClaim _discountClaim)
{
    try
    {
        ttsbegin;

        if (_discountClaim.Status == GUPDiscountClaimStatus::Calculated)
        {
            _discountClaim.selectForUpdate(true);

            this.post(_discountClaim);

            _discountClaim.Status = GUPDiscountClaimStatus::Claimed;
            _discountClaim.update();
        }

        ttscommit;
    }
    catch (Exception::Error)
    {
        exceptionTextFallThrough();
    }
}

public NumberSequenceCode ledgerJournalNameVoucher(LedgerJournalName _ledgerJournalName)
{
    NumberSequenceTable numberSequenceTable = NumberSequenceTable::find(_ledgerJournalName.NumberSequenceTable);

    return numberSequenceTable.NumberSequence;
}

protected void post(GUPDiscountClaim _gupDiscountClaim)
{
    NumberSeq                    numberSeq;
    LedgerJournalTable           ledgerJournalTable;
    GUPDiscountClaimTransaction  discountClaimTransaction;
    SalesLine                    salesLine;
    date                         processDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());


    numberSeq = NumberSeq::newGetVoucherFromCode(this.ledgerJournalNameVoucher(this.ledgerJournalNameProcess()),
                                                 NumberSeqScopeFactory::createDefaultScope(),
                                                 false);

    ttsbegin;

    Voucher voucher = numberSeq.voucher();

    ledgerJournalTable = this.createClaimLedgerJournalTable(this.ledgerJournalNameProcess());

    this.createVendLedgerJournalTrans(_gupDiscountClaim,
                                      ledgerJournalTable.JournalNum,
                                      voucher,
                                      _gupDiscountClaim.totalClaimAmount(),
                                      processDate);

    while select sum(Amount) from discountClaimTransaction
        where discountClaimTransaction.DiscountClaimId == _gupDiscountClaim.DiscountClaimId
        outer join DefaultDimension, RecId from salesLine
            group by salesLine.DefaultDimension
            where salesLine.InventTransId == discountClaimTransaction.InventTransId
    {
        this.createAccrualReversalLedgerJournalTrans(_gupDiscountClaim,
                                                     salesLine.DefaultDimension,
                                                     ledgerJournalTable.JournalNum,
                                                     voucher,
                                                     discountClaimTransaction.Amount,
                                                     processDate);
    }

    ttscommit;

    LedgerJournalPost::postJournal(ledgerJournalTable, NoYes::No);
}

protected LedgerJournalTable createClaimLedgerJournalTable(LedgerJournalName _ledgerJournalName)
{
    LedgerJournalTable ledgerJournalTable;
    ledgerJournalTable = ledgerJournalTable.pdsInitFromledgerJournalName(_ledgerJournalName);
    ledgerJournalTable.insert();
    return ledgerJournalTable;
}

protected void createVendLedgerJournalTrans(
    GUPDiscountClaim _gupDiscountClaim, 
    LedgerJournalId _journalNum, 
    Voucher _voucher, 
    Amount _claimAmount, 
    date _processDate)
{
    LedgerJournalTrans ledgerJournalTrans;

    ledgerJournalTrans.initValue();
    ledgerJournalTrans.JournalNum            = _journalNum;
    ledgerJournalTrans.AccountType           = LedgerJournalACType::Vend;
    ledgerJournalTrans.Voucher               = _voucher;

    ledgerJournalTrans.parmAccount(_gupDiscountClaim.VendorAccount);

    // Set text: Discount claim
    ledgerJournalTrans.Txt                   = "@GlobalUnifiedPricing:DiscountClaim";

    if (_claimAmount >= 0)
    {
        ledgerJournalTrans.AmountCurCredit   = 0;
        ledgerJournalTrans.AmountCurDebit    = _claimAmount;
    }
    else
    {
        ledgerJournalTrans.AmountCurDebit    = 0;
        ledgerJournalTrans.AmountCurCredit   = abs(_claimAmount);
    }

    ledgerJournalTrans.Approved             = NoYes::Yes;
    ledgerJournalTrans.Approver             = HcmWorker::userId2Worker(curUserId());
    ledgerJournalTrans.DocumentDate         = _processDate;
    ledgerJournalTrans.CurrencyCode         = _gupDiscountClaim.CurrencyCode;
    ledgerJournalTrans.TransDate            = _processDate;
    ledgerJournalTrans.Invoice              = this.getVendorInvoiceClaimJournalNumberSeq().num();

    _gupDiscountClaim.VendorClaimInvoice = ledgerJournalTrans.Invoice;
    _gupDiscountClaim.update();

    this.setLedgerJournalTransCurrencyExchRate(ledgerJournalTrans);

    ledgerJournalTrans.insert();
}

protected void createAccrualReversalLedgerJournalTrans(
    GUPDiscountClaim _gupDiscountClaim,
    InventSiteLinkedDimensionValueSet _defaultDimension,
    LedgerJournalId _journalNum, 
    Voucher _voucher, 
    Amount _claimTransAmount, 
    date _processDate)
{
    LedgerJournalTrans ledgerJournalTrans;

    List dimensionSourcesOriginal = new List(Types::Class);
    dimensionSourcesOriginal.addEnd(LedgerDimensionDefaultingEngine::getDefaultDimensionSpecifiers(_defaultDimension));

    ledgerJournalTrans.clear();
    ledgerJournalTrans.initValue();
    ledgerJournalTrans.JournalNum            = _journalNum;
    ledgerJournalTrans.AccountType           = LedgerJournalACType::Ledger;
    ledgerJournalTrans.Voucher               = _voucher;
    ledgerJournalTrans.LedgerDimension       = LedgerDimensionDefaultingEngine::createLedgerDimension(_gupDiscountClaim.LedgerDimension, dimensionSourcesOriginal);

    ledgerJournalTrans.Txt                   = strFmt("%1 %2 %3", "@GlobalUnifiedPricing:DiscountClaimAccrual", "@SYS77038", "@SYS8776");

    if (_claimTransAmount >= 0)
    {
        ledgerJournalTrans.AmountCurCredit   = _claimTransAmount;
        ledgerJournalTrans.AmountCurDebit    = 0;
    }
    else
    {
        ledgerJournalTrans.AmountCurDebit    = abs(_claimTransAmount);
        ledgerJournalTrans.AmountCurCredit   = 0;
    }

    ledgerJournalTrans.Approved              = NoYes::Yes;
    ledgerJournalTrans.Approver              = HcmWorker::userId2Worker(curUserId());
    ledgerJournalTrans.DocumentDate          = _processDate;
    ledgerJournalTrans.CurrencyCode          = _gupDiscountClaim.CurrencyCode;
    ledgerJournalTrans.TransDate             = _processDate;
    ledgerJournalTrans.Invoice               = this.getVendorInvoiceClaimJournalNumberSeq().num();

    this.setLedgerJournalTransCurrencyExchRate(ledgerJournalTrans);

    ledgerJournalTrans.insert();
}

protected NumberSeq getVendorInvoiceClaimJournalNumberSeq()
{
    NumberSeq               numberSeq;
    NumberSequenceReference numberSequenceReference;
    NumberSequenceTable     numberSequenceTable;

    numberSequenceReference = GUPParameters::numRefDiscountVendorClaimJournalInvoice();

    numberSequenceTable = NumberSequenceTable::find(numberSequenceReference.NumberSequenceId);

    if (numberSequenceTable)
    {
        if (numberSequenceTable.Manual == NoYes::Yes)
        {
            throw error(strFmt("@SYS131762", "@GlobalUnifiedPricing:GUPDiscountVendorClaimJournalInvoice"));
        }
        else
        {
            numberSeq = NumberSeq::newGetNum(numberSequenceReference);
        }
    }

    if (numberSeq == null)
    {
        throw error(strfmt("@GLS111556", new DictType(extendedtypenum(GUPDiscountVendorClaimJournalInvoice)).label(), "@GlobalUnifiedPricing:GUPParameters"));
    }

    return numberSeq;
}
